    # ---------------------------------------------------------------- I.1
    anhang("I.1", "I1", "Praxisbeispiele_entlang_des_Vertragsprozesses", "Anhang I.1: Praxisbeispiele entlang des Vertragsprozesses",
        "Die **Praxisbeispiele** führen durchgängige Fälle vom **Angebot** bis zur **Beendigung**: gewerblicher Kunde mit Sammelrechnung, Privatkunde mit E-Signatur, KAM betreuter Großkunde mit Sonderfall, Reifenvertrag. Dieser Guide zeigt, wie Sie die Beispiele **nachvollziehen** und im **Training** nutzen.",
        ["**Dealer**: Beispiele für Angebot, Antrag, Signatur", "**MO**: Beispiele für Prüfung und Ablehnung", "**Trainer**: Beispiele als Übungsfälle"],
        ["Testumgebung oder Schulungssystem", "Testdaten aus Anhang I.3", "Kapitel 4 bis 10 gelesen"],
        cols(T("Beispiele", ["Beispiel 1: Gewerblicher Kunde, Sammelrechnung, Unterschrift per E-Mail", "Beispiel 2: Privatkunde, E-Signatur per QR-Code", "Beispiel 3: KAM betreuter Großkunde mit Sonderfallanfrage", "Beispiel 4: Reifenvertrag (Kapitel 13)"]),
             T("Durchgängige Phasen", ["Angebot und Antrag (Kapitel 5 und 6)", "Zahlung und Signatur (Kapitel 7)", "Prüfung und Aktivierung (Kapitel 8 und 9)", "Änderung und Beendigung (Kapitel 10)"])),
        ["Wählen Sie das **Beispiel**, das Ihrer Rolle und Kundengruppe entspricht.",
         "Führen Sie die Schritte im **Schulungssystem** mit den angegebenen **Testdaten** durch (Anhang I.3).",
         "Vergleichen Sie an jedem **Kontrollpunkt** Ihren Status mit dem im Beispiel dokumentierten Status.",
         "Bei Abweichungen prüfen Sie Kapitel und Klärungsregister; melden Sie neue Abweichungen (Anhang F).",
         "Nutzen Sie die Beispiele für **Wissenschecks** (Anhang H) und Rechenbeispiele (Anhang I.2)."],
        "~~Praxisbeispiele nur im Schulungs- oder Testsystem durchführen.~~ Im Produktivsystem entstehen echte Anträge mit Prüfung durch das Kundenmanagement.",
        ["Beispiel 1 entspricht dem Fall der Van-Vorlage „Antragserstellung und -verwaltung“.", "Spartenunterschiede sind in den Beispielen markiert (Kapitel 21).", "Kontrollpunkte entsprechen den Checklisten in Anhang B."],
        ["Passendes Beispiel gewählt", "Mit Testdaten im Schulungssystem durchgeführt", "Status an Kontrollpunkten verglichen", "Abweichungen gemeldet"],
        [("Welches Beispiel passt für Van-Händler?", "Beispiel 1 (gewerblicher Kunde) und Beispiel 2 (Privatkunde), beide mit Van-Kennungen."),
         ("Gibt es Beispiele für Ablehnungen?", "Ja, Beispiel 3 enthält eine Sonderfallanfrage mit Ablehnung und Wiederaufnahme."),
         ("Woher kommen die Testdaten?", "Aus dem Testdatenkatalog in Anhang I.3.")],
        ["__Praxisbeispiele__ – Anhang I.1.", "__Testdatenkatalog__ – Anhang I.3.", "__Rechenbeispiele__ – Anhang I.2.", LINK_HB],
        ["Beispiel wählen", "Im Schulungssystem durchführen", "Kontrollpunkte vergleichen", "Abweichung melden", "Für Training nutzen"], [5, 6, 7, 8, 9, 10], "Praxisbeispiele", "Beispiel 1: Antrag gewerblicher Kunde")

    # ---------------------------------------------------------------- I.2
    anhang("I.2", "I2", "Rechenbeispiele_und_Finanzbezug", "Anhang I.2: Rechenbeispiele und Finanzbezug",
        "Die **Rechenbeispiele** zeigen, wie sich **Preis, Zahlungsintervall, Laufzeit und Laufleistung** auf Zahlplan, **Endabrechnung** und **Erstattung** auswirken, und wie **Rabatte und Kampagnen** wirken. Dieser Guide erklärt die Beispiele Schritt für Schritt.",
        ["**Dealer**: Zahlplan und Preisinformation erklären", "**Fachbereich Finanzen**: Endabrechnung und Korrekturen", "**Markt**: Preiskomponenten und Faktoren (Kapitel 14.9, 14.14)"],
        ["Produkt und Konfiguration des Beispielvertrags", "Preisversion des Marktes bekannt", "Kapitel 11 gelesen"],
        cols(T("Beispiele", ["Zahlplan: einmalig gegenüber monatlich", "Laufzeit und Laufleistung: Wirkung auf den Preis", "Kampagne und Händlerrabatt im Angebot", "Vorzeitige Beendigung: Endabrechnung und Erstattung"]),
             T("Finanzbezug", ["Rechnungsstellung (Kapitel 11.1)", "Preiskomponenten und Cost Unit Split (Kapitel 14.14)", "Buchung in NEMESIS, Zahlung über MPay (Kapitel 19)"])),
        ["Lesen Sie die **Ausgangsdaten** des Beispiels: Produkt, Laufzeit, Laufleistung, Zahlungsintervall.",
         "Vollziehen Sie den **Zahlplan** nach: Gesamtpreis, Anzahl und Höhe der Raten, Fälligkeiten.",
         "Wenden Sie **Kampagne oder Rabatt** an und prüfen Sie die Wirkung auf den Zahlplan.",
         "Rechnen Sie die **Endabrechnung** bei vorzeitiger Beendigung nach: genutzter Anteil, Erstattung, Korrektur (Kapitel 11.6).",
         "Vergleichen Sie Ihr Ergebnis mit der **Preisinformation** (PDF) aus dem System (Kapitel 5.6)."],
        "~~Die Rechenbeispiele verwenden Beispielpreise.~~ Verbindlich sind ausschließlich die Preisversion des Marktes und die Preisinformation aus oneSCM.",
        ["Das Zahlungsintervall ist nachträglich nur auf „einmalig“ änderbar (Kapitel 6).", "Erstattungen laufen über den Fachbereich Finanzen (Kapitel 11.6).", "Faktorgrenzen und Cluster beschreibt Kapitel 14.9."],
        ["Ausgangsdaten verstanden", "Zahlplan nachgerechnet", "Rabattwirkung geprüft", "Endabrechnung nachvollzogen"],
        [("Warum weicht mein Ergebnis von der Preisinformation ab?", "Prüfen Sie Preisversion, Kampagnenbedingungen und Rundungsregeln; im Zweifel gilt das System."),
         ("Wie wird die Erstattung berechnet?", "Anteilig nach Laufzeit und Laufleistung gemäß Kapitel 11.6; das Beispiel zeigt die Schritte."),
         ("Gilt das Beispiel für Pkw und Van?", "Die Rechenlogik ja, die Preise je Sparte unterscheiden sich (Kapitel 21.3).")],
        ["__Rechenbeispiele und Finanzbezug__ – Anhang I.2.", "__Rechnung, Zahlung, Kosten__ – Kapitel 11.", LINK_HB, LINK_SUPPORT],
        ["Ausgangsdaten lesen", "Zahlplan nachrechnen", "Rabatt anwenden", "Endabrechnung prüfen", "Mit System vergleichen"], [11, 14], "Rechenbeispiele", "Zahlplan im Beispiel")

    # ---------------------------------------------------------------- I.3
    anhang("I.3", "I3", "Testdatenkatalog_und_Nachweise", "Anhang I.3: Testdatenkatalog und Nachweise",
        "Der **Testdatenkatalog** stellt sichere **Beispielkunden, Fahrzeuge, Produkte und Zahlungsdaten** für Schulung, Tests und Bildschirmbilder bereit und dokumentiert die **Nachweise** je Testfall. Dieser Guide zeigt, wie Sie Testdaten **auswählen** und **Nachweise** ablegen.",
        ["**Trainer/Tester**: Testdaten nutzen", "**Markt**: Product Testing (Kapitel 14.12)", "**Redaktion**: Katalog und Nachweise pflegen"],
        ["Schulungs- oder Testsystem", "Testfall oder Praxisbeispiel (Anhang I.1)", "Datenschutzregeln (Kapitel 16.1)"],
        cols(T("Katalog", ["Testkunden: privat, gewerblich, KAM", "Testfahrzeuge je Sparte mit FIN, Baumuster, OTR-Deal-ID", "Testprodukte, Kampagnen, Bankdaten (Testkonten)"]),
             T("Nachweise", ["Testfall, Datum, Release, Umgebung", "Ergebnis und Abweichung", "Bezug zu Ticket und Kapitel (Anhang E)"])),
        ["Wählen Sie aus dem **Katalog** Kunde, Fahrzeug und Produkt passend zum Testfall oder Praxisbeispiel.",
         "Führen Sie den Testfall im **Test- oder Schulungssystem** durch; verwenden Sie nur Testkonten für Bankdaten.",
         "Dokumentieren Sie den **Nachweis**: Testfall, Datum, Release, Umgebung, Ergebnis.",
         "Nutzen Sie Testdaten auch für **Bildschirmbilder** (Anhang G) und **Product Testing** (Kapitel 14.12).",
         "Melden Sie unbrauchbare oder fehlende Testdaten an die Redaktion (Anhang F)."],
        "~~Echte Kunden-, Fahrzeug- oder Bankdaten sind keine Testdaten.~~ Testdaten stammen ausschließlich aus dem Katalog; Produktivdaten sind in Tests und Bildern unzulässig (Kapitel 16.1).",
        ["Testfahrzeuge gibt es je Sparte mit passenden Kennungen (Kapitel 21.2).", "Nachweise sind Voraussetzung für den produktiven Funktionsstand (Kapitel 16.4).", "Der Katalog wird je Release aktualisiert (Kapitel 22)."],
        ["Testdaten aus dem Katalog gewählt", "Testfall im Testsystem durchgeführt", "Nachweis vollständig dokumentiert", "Fehlende Testdaten gemeldet"],
        [("Darf ich ein echtes Fahrzeug im Schulungssystem anlegen?", "Nein, nur Testfahrzeuge aus dem Katalog."),
         ("Wo lege ich den Nachweis ab?", "Im Nachweisregister des Katalogs mit Bezug zu Testfall und Release."),
         ("Gibt es Testdaten für Reifenverträge?", "Ja, Testprodukte mit Reifentyp und Reifengröße (Kapitel 13).")],
        ["__Testdatenkatalog und Nachweise__ – Anhang I.3.", "__Product Testing__ – Kapitel 14.12.", LINK_HB, LINK_SUPPORT],
        ["Testdaten wählen", "Testfall durchführen", "Nachweis dokumentieren", "Für Bilder und Tests nutzen", "Lücken melden"], [14, 16, 17], "Testdaten", "Testdatenkatalog")

    # ---------------------------------------------------------------- Übergangsmodule
    def uebergang(code, key, slug, title, von, nach, ziel, rollen, voraus, themen, schritte, warnung, hinweise, check, fragen, links, flow, shot2):
        G.append(guide(code, slug, title, ziel, rollen, voraus, themen, schritte, warnung, hinweise, check, fragen, links,
                       kind="Übergangsmodul", chs=[von, nach], flow=flow, key=key, overview_title="Übergang im Überblick", shot2=shot2))
        G[-1]["sub"] = "Kapitel %d nach %d" % (von, nach)

    uebergang("T6-7", "T06-07", "Vom_gespeicherten_Antrag_zu_Zahlungsdaten_und_Signatur", "T6-7: Vom gespeicherten Antrag zu Zahlungsdaten und Signatur", 6, 7,
        "Dieses Modul verbindet **Kapitel 6** (Antrag gespeichert, Referenznummer vorhanden) mit **Kapitel 7** (Zahlungsdaten, Dokumente, Unterschrift). Sie prüfen, was beim **Übergang** vorliegen muss, und vermeiden die typischen Brüche zwischen Antrag und Signatur.",
        ["**Dealer**: Übergang durchführen", "**Kunde**: Zahlungsdaten bereitstellen und unterschreiben", "**MO**: liest Signaturstatus in der Prüfung"],
        ["Antrag gespeichert, Referenznummer notiert (Kapitel 6.7)", "Keine roten Validierungsmeldungen", "Kunden-E-Mail und Handynummer im Kundenstamm"],
        cols(T("Ausgangslage (Kapitel 6)", ["Antrag gespeichert, Status „erfasst“", "Kunde, Fahrzeug, Produkt zugeordnet", "Sonderfreigabe erkannt oder nicht nötig"]),
             T("Ziel (Kapitel 7)", ["Zahlungsart, Intervall, Zahler und Rechnungsempfänger erfasst", "SEPA-Mandat und Dokumente erzeugt", "Signatur eingeholt, Status kontrolliert"])),
        ["Öffnen Sie den gespeicherten Antrag über die **Referenznummer** (Kapitel 8.1) und prüfen Sie den **Antragsstatus**.",
         "Stellen Sie sicher, dass der Antrag **vollständig** ist: Ein Antrag mit offener Validierung kann nicht zur Signatur.",
         "Wechseln Sie zur **Kundendatenprüfung** und aktivieren Sie bei Bedarf die **Sammelrechnung** (Kapitel 6 und 7.2).",
         "Erfassen Sie **Zahlungsart, Intervall und Bankdaten** (Kapitel 7.1 bis 7.3).",
         "Erzeugen Sie die **Antragsvorschau** und klicken Sie auf das **Häkchen** zur Unterzeichnung (Kapitel 7.4).",
         "Wählen Sie die **Unterschriftsart** und kontrollieren Sie den **Signaturstatus** (Kapitel 7.5 bis 7.8)."],
        "~~Nach „Antrag erstellen“ sind Produkt, Laufzeit und Laufleistung nicht mehr änderbar.~~ Fehler aus Kapitel 6 lassen sich im Übergang nicht korrigieren; sie erfordern einen Neuvertrag.",
        ["Das Zahlungsintervall lässt sich später nur auf „einmalig“ ändern.", "Bei Sonderfreigaben wartet die Aktivierung auf den MO Check, die Signatur kann trotzdem eingeholt werden.", "Fehlende Kundenkontaktdaten blockieren E-Mail- und SMS-Signatur."],
        ["Antragsstatus geprüft", "Validierung ohne rote Meldungen", "Zahlungsdaten erfasst", "Signaturweg gewählt und Status kontrolliert"],
        [("Kann ich zwischen Speichern und Signatur unterbrechen?", "Ja, der Antrag bleibt unter der Referenznummer in der Antragsverwaltung erreichbar."),
         ("Was, wenn der Kunde die Zahlungsart ändern will?", "Vor der Signatur in Kapitel 7.1 ändern; nach der Signatur ist eine erneute Signatur nötig (Kapitel 7.7)."),
         ("Muss der Zahler unterschreiben?", "Das SEPA-Mandat unterschreibt der Zahler; der Vertrag der Vertragsinhaber (Kapitel 7.2).")],
        ["__Kapitel 6__ – Servicevertrag anlegen und Antrag abschließen.", "__Kapitel 7__ – Zahlungsdaten, Dokumente und Unterschrift.", LINK_HB, LINK_SUPPORT],
        ["Antrag öffnen", "Vollständigkeit prüfen", "Kundendaten und Sammelrechnung", "Zahlungsdaten erfassen", "Vorschau und Häkchen", "Signatur einholen"], "Übergang zur Unterzeichnung")

    uebergang("T7-8", "T07-08", "Von_Dokumenten_und_Signatur_zur_Aktivierungspruefung", "T7-8: Von Dokumenten und Signatur zur Aktivierungsprüfung", 7, 8,
        "Dieses Modul verbindet **Kapitel 7** (Signatur und Dokumente liegen vor) mit **Kapitel 8** (Antrag verfolgen und aktivieren). Sie stellen sicher, dass alle **Aktivierungsvoraussetzungen** erfüllt sind, bevor das Kundenmanagement prüft.",
        ["**Dealer**: Daten und Dokumente vervollständigen", "**Kundenmanagement/MO**: Prüfung und Aktivierung", "**System**: automatische Aktivierung bei Vollständigkeit"],
        ["Signaturstatus „unterschrieben“ (Kapitel 7.8)", "Vertragsdokument und SEPA-Mandat abgelegt", "Erstzulassung, Kennzeichen und ZB II verfügbar"],
        cols(T("Ausgangslage (Kapitel 7)", ["Signatur digital oder manuell eingeholt", "Dokumente im System abgelegt oder hochgeladen", "Zahlungsdaten vollständig"]),
             T("Ziel (Kapitel 8)", ["Erstzulassung und Kennzeichen ergänzt", "ZB II hochgeladen", "Antrag vollständig eingereicht, Aktivierung erfolgt"])),
        ["Prüfen Sie in der **Antragsverwaltung** den **Signatur- und Dokumentstatus** (Kapitel 7.8 und 8.1).",
         "Öffnen Sie über „**…**“ die Aktion „**Aktualisieren**“ und ergänzen Sie **Erstzulassungsdatum** und **Kennzeichen** (Kapitel 8.3).",
         "Laden Sie im Register „**Kommunikation**“ die Kopie der **ZB I/ZB II** und bei Druckvariante das unterschriebene Dokument hoch.",
         "Kontrollieren Sie, dass keine **offene Sonderfreigabe** die Aktivierung blockiert (Kapitel 6.5 und 9).",
         "Verfolgen Sie den **Antragsstatus** bis zur Aktivierung und reagieren Sie auf Rückfragen des Kundenmanagements (Kapitel 8.6 und 8.7)."],
        "~~Ohne Erstzulassung, Kennzeichen und ZB II findet keine Aktivierung statt~~, auch wenn der Antrag unterschrieben ist. Das Hochladen ist systemseitig kein Pflichtfeld.",
        ["Bei E-Signatur und E-Mail-Signatur sind die Vertragsdokumente automatisch abgelegt; bei Druck müssen sie hochgeladen werden.", "Falsche Anträge werden abgelehnt, der Kunde erhält eine Information.", "Die Frist von 12 Monaten bzw. 50.000 km nach Erstzulassung gilt (Kapitel 23.1)."],
        ["Signatur- und Dokumentstatus geprüft", "Erstzulassung und Kennzeichen ergänzt", "ZB II hochgeladen", "Keine offene Sonderfreigabe"],
        [("Der Kunde hat unterschrieben, der Antrag ist aber nicht aktiv. Warum?", "Meist fehlen Erstzulassung, Kennzeichen oder ZB II; prüfen Sie Kapitel 8.3."),
         ("Kann ich die ZB II nachreichen?", "Ja, jederzeit über Antragsverwaltung › Referenznummer › Kommunikation."),
         ("Wer aktiviert den Vertrag?", "Bei vollständigen Daten das System, sonst das Kundenmanagement nach Prüfung (Kapitel 8.5).")],
        ["__Kapitel 7__ – Zahlungsdaten, Dokumente und Unterschrift.", "__Kapitel 8__ – Antrag verfolgen und aktivieren.", LINK_HB, LINK_SUPPORT],
        ["Signaturstatus prüfen", "Aktualisieren öffnen", "Erstzulassung und Kennzeichen", "ZB II hochladen", "Sonderfreigabe prüfen", "Aktivierung verfolgen"], "Aktualisieren in der Antragsverwaltung")

    uebergang("T8-9", "T08-09", "Gesamtprozess_und_MO_Rollenvertiefung", "T8-9: Gesamtprozess und MO-Rollenvertiefung", 8, 9,
        "Dieses Modul verbindet die **Dealer-Sicht** auf den Antrag (**Kapitel 8**) mit der **MO-Sicht** der fachlichen Prüfung (**Kapitel 9**). Sie verstehen, was der MO prüft, wie Rückmeldungen beim Dealer ankommen und wie beide Rollen den **Gesamtprozess** gemeinsam abschließen.",
        ["**Dealer**: Antrag vollständig einreichen, Rückfragen beantworten", "**MO**: Prüfung, Genehmigung, Zurückweisung", "**Kundenmanagement**: Aktivierung und Kundeninformation"],
        ["Antrag vollständig eingereicht (Kapitel 8)", "MO-Rolle und Prüfkriterien bekannt (Kapitel 9.1)", "Kommunikationsweg zwischen Dealer und MO geklärt"],
        cols(T("Dealer-Sicht (Kapitel 8)", ["Antrag verfolgen und Status lesen", "Fehlende Daten und Dokumente ergänzen", "Ablehnung und Wiederaufnahme"]),
             T("MO-Sicht (Kapitel 9)", ["Arbeitsliste MO-Check", "Prüfkriterien, Prüfstatus, Gründe", "Genehmigen, zurückweisen, übergeben"])),
        ["Ordnen Sie den Antrag in den **Gesamtprozess** ein: eingereicht → in Prüfung → genehmigt/zurückgewiesen → aktiv (Anhang D).",
         "Als MO öffnen Sie den Antrag aus der **Arbeitsliste** und prüfen gegen die **Kriterien** (Kapitel 9.2 und 9.4).",
         "Als Dealer lesen Sie den **Prüfstatus** und die **Gründe** in der Kommunikation (Kapitel 8.2 und 9.3).",
         "Bei **Zurückweisung** korrigiert der Dealer und reicht erneut ein; der MO prüft erneut (Kapitel 8.7 und 9.5).",
         "Nach **Genehmigung** erfolgt die Aktivierung; beide Rollen kontrollieren das Ergebnis (Kapitel 8.6 und 9.6)."],
        "~~Dealer und MO kommunizieren über den Antrag, nicht über private Kanäle.~~ Gründe und Rückfragen gehören in die Kommunikation des Antrags, damit sie nachvollziehbar bleiben.",
        ["Zurückweisungen brauchen immer einen Kommentar (Kapitel 9).", "Sonderfreigaben aus Kapitel 12 laufen über denselben MO Check.", "Contract-Review-Profile geben dem MO die Übersicht (Kapitel 9.8)."],
        ["Antragsstatus im Gesamtprozess bekannt", "Prüfkriterien beiden Rollen klar", "Rückmeldung über den Antrag dokumentiert", "Ergebnis von beiden Rollen kontrolliert"],
        [("Wie erfährt der Dealer vom Prüfergebnis?", "Über Status und Kommunikation in der Antragsverwaltung (Kapitel 8.2)."),
         ("Kann der MO Daten selbst korrigieren?", "Der MO prüft; Korrekturen am Antrag nimmt der Dealer vor (Kapitel 9.5)."),
         ("Wie lange dauert ein MO Check?", "Abhängig von Vollständigkeit und Arbeitsliste; vollständige Anträge werden zuerst bearbeitet.")],
        ["__Kapitel 8__ – Antrag verfolgen und aktivieren.", "__Kapitel 9__ – MO Checks und fachliche Prüfungen.", "__Rollen-/Status-/Scopematrizen__ – Anhang D.", LINK_HB],
        ["Gesamtprozess einordnen", "MO prüft", "Dealer liest Status", "Korrektur und erneute Prüfung", "Aktivierung kontrollieren"], "Arbeitsliste MO-Check und Antragsverwaltung")

    uebergang("T9-10", "T09-10", "Vom_Pruefergebnis_zur_laufenden_Vertragsverwaltung", "T9-10: Vom Prüfergebnis zur laufenden Vertragsverwaltung", 9, 10,
        "Dieses Modul verbindet das **Prüfergebnis** (**Kapitel 9**, genehmigt und aktiviert) mit der **laufenden Vertragsverwaltung** (**Kapitel 10**). Sie wissen, welche Daten mit der Aktivierung festgeschrieben sind, was im Alltag änderbar bleibt und wann Änderungen erneut geprüft werden.",
        ["**MO**: Prüfung abschließen, Änderungen prüfen", "**Dealer**: Vertrag im Alltag verwalten", "**Fachbereich Finanzen**: Zahlplan und Folgen"],
        ["Vertragsstatus „aktiv“ (Kapitel 8.6)", "Prüfergebnis dokumentiert (Kapitel 9.3)", "Zuständigkeiten für Änderungen bekannt (Kapitel 10)"],
        cols(T("Ausgangslage (Kapitel 9)", ["Prüfung abgeschlossen, Vertrag aktiv", "Prüfstatus und Gründe in der Historie", "Übergabe an Support, falls strittig"]),
             T("Ziel (Kapitel 10)", ["Vertrag suchen und Details prüfen", "Zulässige Änderungen kennen", "Änderungen erneut prüfen lassen (Kapitel 9.7)"])),
        ["Prüfen Sie nach der Aktivierung die **Vertragsdetails** und den **Zahlplan** (Kapitel 10.1 und 11.1).",
         "Kennen Sie die **festgeschriebenen Daten**: Produkt, Laufzeit, Laufleistung, Zahlungsintervall (nur auf „einmalig“ änderbar).",
         "Nutzen Sie im Alltag die **zulässigen Aktionen**: Kunden- und Zahlungsdaten, Zahlerwechsel, Aussetzen, Folgeangebot (Kapitel 10.2 bis 10.5).",
         "Änderungen mit Prüfbedarf gehen erneut in den **MO Check** (Kapitel 9.7).",
         "Dokumentieren Sie jede Änderung nachvollziehbar in der **Historie** (Kapitel 10.8)."],
        "~~Mit der Aktivierung beginnen Zahlplan und Leistungsanspruch.~~ Änderungen an Produkt oder Laufzeit sind nur über Neuvertrag möglich; Beendigungen haben finanzielle Folgen (Kapitel 10.6 und 11.6).",
        ["Die Prüfhistorie aus Kapitel 9 bleibt am Vertrag sichtbar.", "Übergangsmodul T6-7 beschreibt den Beginn, dieses Modul das Ende des Antragsprozesses.", "Reporting zu aktiven Verträgen in Kapitel 11.7."],
        ["Vertragsdetails und Zahlplan nach Aktivierung geprüft", "Festgeschriebene Daten bekannt", "Zulässige Änderungen bekannt", "Änderung mit Prüfbedarf an MO gegeben"],
        [("Kann der MO einen aktiven Vertrag zurücknehmen?", "Nein, nach Aktivierung gelten die Regeln aus Kapitel 10.6 für Stornierung und Beendigung."),
         ("Welche Änderungen lösen einen MO Check aus?", "Zahlerwechsel, Vertragsübertragung und Sonderkonditionen (Kapitel 9.7 und 10.3)."),
         ("Wo sehe ich das Prüfergebnis später?", "In der Änderungshistorie des Vertrags (Kapitel 10.8).")],
        ["__Kapitel 9__ – MO Checks und fachliche Prüfungen.", "__Kapitel 10__ – Verträge im Alltag verwalten.", LINK_HB, LINK_SUPPORT],
        ["Details nach Aktivierung prüfen", "Festgeschriebene Daten kennen", "Zulässige Änderungen nutzen", "Erneut prüfen lassen", "Historie dokumentieren"], "Vertragsdetails nach Aktivierung")

